import math
h = [1, 0]
out = {'cat': [1, 0], 'dog': [0, 1], 'fish': [-1, 0]}
score = {w: sum(a*b for a, b in zip(v, h)) for w, v in out.items()}
e = {w: math.exp(s) for w, s in score.items()}
Z = sum(e.values())
print(round(Z, 3))
for w in ['cat', 'dog', 'fish']:
    print('%.3f' % (e[w] / Z))
